:root {
    --main-loader-color: #3b82f6;
    --progress: 0%;
    --progress-num: 0;
  }
  
  body.dark-theme {
    --main-loader-color: #3b82f6;
  }
  
  body.white-theme {
    --main-loader-color: #6366f1;
  }
  
  body.pink-theme {
    --main-loader-color: #ec4899;
  }
  
  html.black-theme,
  body.black-theme {
    --main-loader-color: #fbbf24;
  }
  
  .loader::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: var(--main-loader-color);
    transform: scaleX(calc(var(--progress-num, 0) * 0.01));
    transform-origin: left center;
    border-radius: 0;
    backface-visibility: hidden;
  }
  
  .loader.is-animating::before {
    transition: none;
    will-change: transform;
  }
  
  .loader.is-complete::before {
    transition: transform 0.32s cubic-bezier(0, 0, 0.58, 1);
    will-change: auto;
  }
  
  @media (prefers-reduced-motion: reduce) {
    .loader.is-complete::before {
      transition: none;
    }
  }
  
