      height: auto !important;
      display: block !important;
      overflow: visible !important;
  }

  .mdpdf-pdf-export pre {
      overflow: visible !important;
      white-space: pre-wrap !important;
      word-break: break-word !important;
  }

  .mdpdf-pdf-render-host {
      font-family: "Atlassian Sans", Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }

  .livecode-rename-modal-overlay {
      position: fixed;
      inset: 0;
      z-index: 10100;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 16px;
      background: rgba(15, 23, 42, 0.55);
  }
  .livecode-rename-modal {
      width: min(420px, 92vw);
      border-radius: 12px;
      border: 1px solid rgba(148, 163, 184, 0.24);
      background: #1f2937;
      color: #e5e7eb;
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.35);
      padding: 16px;
  }
  body.white-theme .livecode-rename-modal {
      background: #ffffff;
      color: #1f2937;
      border-color: rgba(71, 85, 105, 0.18);
  }
  .livecode-rename-modal-title {
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 12px;
  }
  .livecode-rename-modal-input {
      width: 100%;
      box-sizing: border-box;
      border-radius: 8px;
      border: 1px solid rgba(148, 163, 184, 0.28);
      background: rgba(15, 23, 42, 0.35);
      color: inherit;
      padding: 10px 12px;
      font: inherit;
      margin-bottom: 14px;
  }
  body.white-theme .livecode-rename-modal-input {
      background: #f8fafc;
      border-color: rgba(71, 85, 105, 0.22);
  }
  .livecode-rename-modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 8px;
  }

  /* Keep agent activity feed text visually uniform (verb, detail, meta, thought). */
  html body #livecode-chat-messages .livecode-agent-steps .livecode-activity-line,
  html body #livecode-chat-messages .livecode-agent-steps .livecode-activity-text,
  html body #livecode-chat-messages .livecode-agent-steps .livecode-activity-verb,
  html body #livecode-chat-messages .livecode-agent-steps .livecode-activity-detail,
  html body #livecode-chat-messages .livecode-agent-steps .livecode-activity-meta,
  html body #livecode-chat-messages .livecode-agent-steps .livecode-activity-file-link,
  html body #livecode-chat-messages .livecode-agent-steps .livecode-text-shimmer {
      font-size: var(--livecode-chat-text-size) !important;
      font-weight: 400 !important;
      line-height: 1.5 !important;
  }

  /* Inline code chips should match body text size, not tower over it. */
  html body #livecode-chat-messages .chat-msg :not(pre) > code:not(.code-card code):not(.livecode-code-card code) {
      display: inline !important;
      padding: 0.08em 0.32em !important;
      margin: 0 !important;
      font-size: 0.92em !important;
      font-weight: 400 !important;
      line-height: inherit !important;
      vertical-align: baseline !important;
  }
